            [177] = { str = "#optional Go to #COORD[76,60]# in Stormwind City. Talk to Master Mathias Shaw Remember to re-equip your main weapon if you switched to a Dagger earlier Turn in #INKlaven's Tower#. Target #NPCMaster Mathias Shaw#. (Rogue only)", x = 76, y = 60, zone = "Stormwind City" },
